import React,{useEffect,useMemo,useState}from 'react';
import './App.css';
import {roadmap,topicInfo,problems,leaders} from './data/content';

const nav=[['Home','/'],['Roadmap','/roadmap'],['Learn','/learn/arrays'],['Practice','/practice'],['Visualizer','/visualizer'],['Leaderboard','/leaderboard']];
const go=(to)=>{window.history.pushState({},'',to);window.dispatchEvent(new PopStateEvent('popstate'))};
function Button({children,onClick,kind=''}){return <button className={'btn '+kind} onClick={onClick}>{children}<span>→</span></button>}
function Progress({value}){return <div className="progress"><i style={{width:value+'%'}}/></div>}
function Navbar({openSearch}){const [path,setPath]=useState(location.pathname),[open,setOpen]=useState(false);useEffect(()=>{const f=()=>setPath(location.pathname);addEventListener('popstate',f);return()=>removeEventListener('popstate',f)},[]);return <header><a className="brand" href="/" onClick={e=>{e.preventDefault();go('/')}}><b>ACM</b><span>BV</span><em>DSA</em></a><nav className={open?'shown':''}>{nav.map(([n,p])=><a key={p} className={path===p?'active':''} onClick={()=>{go(p);setOpen(false)}}>{n}</a>)}</nav><div className="nav-right"><button className="search-small" onClick={openSearch}>⌕ <span>Search</span><kbd>⌘ K</kbd></button><a onClick={()=>go('/progress')} className={path==='/progress'?'active':''}>Progress</a><button className="avatar">PJ</button></div><button className="hamburger" onClick={()=>setOpen(!open)} aria-label="Menu">{open?'×':'☰'}</button></header>}
function Footer(){return <footer><div><div className="brand"><b>ACM</b><span>BV</span><em>DSA</em></div><p>Learn. Visualize. Solve. Compete.</p><small>An initiative by ACM Student Chapter<br/>Banasthali Vidyapith</small></div><div className="footer-links">{nav.map(([n,p])=><a key={p} onClick={()=>go(p)}>{n}</a>)}<a href="https://acm-bv.acm.org/" target="_blank" rel="noreferrer">ACM BV ↗</a></div><small>© 2026 ACM Student Chapter, Banasthali Vidyapith</small></footer>}
function GraphVisual(){return <div className="graph-visual"><svg viewBox="0 0 420 270"><path d="M210 38L105 112M210 38l105 74M105 112l-58 82m58-82 57 82m48-82 58 82"/><circle cx="210" cy="38" r="25"/><circle cx="105" cy="112" r="25"/><circle cx="315" cy="112" r="25"/><circle cx="47" cy="194" r="25"/><circle cx="162" cy="194" r="25"/><circle cx="373" cy="194" r="25"/></svg><div className="graph-num n1">10</div><div className="graph-num n2">5</div><div className="graph-num n3">15</div><div className="graph-num n4">3</div><div className="graph-num n5">7</div><div className="graph-num n6">20</div><code>binary_search_tree</code></div>}
function Stats(){return <section className="stats">{[['250+','Concepts & Lessons'],['500+','Practice Problems'],['30+','Interactive Visualizations'],['12','Learning Modules']].map(([n,l])=><div key={l}><b>{n}</b><span>{l}</span></div>)}</section>}
function Timeline({full=false}){const [filter,setFilter]=useState('All');const data=roadmap.filter(x=>filter==='All'||x.difficulty===filter);return <section className={'timeline '+(full?'timeline-full':'')}><div className="section-top">{full&&<><p className="eyebrow">CURRICULUM / 12 MODULES</p><h1>DSA ROADMAP</h1><p className="muted">A structured path from fundamentals to advanced problem solving.</p><div className="roadmap-meta"><div><span>OVERALL PROGRESS</span><b>38%</b><Progress value={38}/></div><div><span>ESTIMATED JOURNEY</span><b>10–14 weeks</b></div></div><div className="filters">{['All','Beginner','Intermediate','Advanced'].map(f=><button className={f===filter?'selected':''} onClick={()=>setFilter(f)} key={f}>{f}</button>)}</div></>} {!full&&<><p className="eyebrow">THE CURRICULUM</p><h2>YOUR DSA JOURNEY</h2><p className="muted">From your first array to advanced algorithms.</p></>}</div><div className="timeline-list">{data.map((item,i)=><article className={'roadmap-card '+(item.progress===100?'done':'')+(item.progress>0&&item.progress<100?' current':'')} key={item.id}><div className="timeline-node">{item.progress===100?'✓':item.progress?'◉':'⌾'}</div><span className="step mono">{item.number}</span><div className="roadmap-content"><div><span className="pill">{item.difficulty}</span><h3>{item.title}</h3><p>{item.description}</p></div><div className="roadmap-side"><span className="mono">{item.lessons} LESSONS</span><Progress value={item.progress}/><b>{item.progress}%</b><Button onClick={()=>go('/learn/'+(topicInfo[item.id]?item.id:'arrays'))}>{item.progress?'Continue':'Explore'}</Button></div></div></article>)}</div></section>}
function Home(){return <><main className="hero"><div className="hero-copy"><p className="eyebrow">ACM STUDENT CHAPTER · BANASTHALI VIDYAPITH</p><h1>MASTER DSA.<br/><span>ONE CONCEPT<br/>AT A TIME.</span></h1><p className="lead">Learn data structures and algorithms through interactive lessons, visualizations, challenges, and practice — built by ACM Student Chapter, Banasthali Vidyapith.</p><div className="actions"><Button onClick={()=>go('/roadmap')}>Start Your Journey</Button><Button kind="ghost" onClick={()=>go('/roadmap')}>Explore Roadmap</Button></div></div><GraphVisual/></main><Stats/><section className="why"><p className="eyebrow">WHY THIS MATTERS</p><h2>WHY LEARN DSA?</h2><div className="feature-grid">{[['◈','Problem Solving','Build structured thinking and logical reasoning.'],['⌘','Technical Interviews','Prepare for coding and technical interviews.'],['↗','Competitive Programming','Develop algorithmic thinking and speed.'],['▣','Software Engineering','Understand efficient data processing.'],['◌','Academic Foundation','Strengthen your computer science fundamentals.']].map(x=><article key={x[1]}><i>{x[0]}</i><h3>{x[1]}</h3><p>{x[2]}</p></article>)}</div></section><Timeline/><Challenge/><Everywhere/><EventTimeline/><section className="acm-callout"><p className="eyebrow">ACM STUDENT CHAPTER · BV</p><h2>BUILT FOR THE<br/>ACM BV COMMUNITY</h2><p>An interactive learning initiative by ACM Student Chapter, Banasthali Vidyapith.</p><Button onClick={()=>window.open('https://acm-bv.acm.org/','_blank')}>Visit ACM BV</Button></section></>}
function Challenge(){return <section className="challenge"><div><p className="eyebrow">DAILY DSA CHALLENGE</p><span className="challenge-day mono">DAY 19</span><h2>Maximum Subarray</h2><p>Find the contiguous subarray with the largest sum.</p><span className="pill medium">Medium</span> <b className="xp">+40 XP</b><br/><Button onClick={()=>go('/practice')}>Attempt Challenge</Button></div><div className="streak"><span>🔥</span><b>7 DAY<br/>STREAK</b><small>Keep your momentum going.</small></div></section>}
